import { HoundApp, InMemoryStorage } from 'hound/';

const { hound } = new HoundApp({
  db: new InMemoryStorage(),
});

import { HoundApp } from 'hound/';
import { connect } from 'npm:ioredis';

const redis = new connect(Deno.env.get('REDIS_URL'));

const { hound } = new HoundApp({ db: redis });

import { HoundApp, DenoKvStorage } from 'hound/';

const kv = await Deno.openKv();
const { hound } = new HoundApp({
  db: new DenoKvStorage(kv),
});
